def _read_backend_marker():
    """读取索引构建时的后端标记，返回 dict 或 None。"""
    if not os.path.exists(BACKEND_MARKER_PATH):
        return None
    try:
        with open(BACKEND_MARKER_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _write_backend_marker(backend, model=None, dim=None, pages=None):
    """记录本次构建所用后端（供查询/增量时保持一致）。"""
    os.makedirs(K.INDEX_DIR, exist_ok=True)
    marker = {
        "backend": backend,
        "model": model,
        "dim": dim,
        "pages": pages,
        "built_at": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    K.write_json_atomic(BACKEND_MARKER_PATH, marker, ensure_ascii=False, indent=1)
    return marker


def _active_backend():
    """返回已有索引应当使用的后端 (backend, model_name)。

    优先依据标记文件（保证与构建时一致，避免 st(768维) 与
    tfidf(256维) 向量维度不匹配）；若无标记则回退到运行时检测。
    """
    marker = _read_backend_marker()
    if marker and marker.get("backend") in ("st", "tfidf"):
        return marker["backend"], marker.get("model")
    return detect_backend(), None


# ---------------------------------------------------------------- 模型加载

def _configure_hf_endpoint():
    """在导入 huggingface_hub 前配置下载端点。

    若用户已显式设置 HF_ENDPOINT 则尊重其选择；否则快速探测
    huggingface.co 是否可达，不可达时回退到镜像 hf-mirror.com。
    模型仍缓存在 HuggingFace 默认目录（~/.cache/huggingface）。
    """
    if os.environ.get("HF_ENDPOINT"):
        return os.environ["HF_ENDPOINT"]
    import socket
    reachable = True
    try:
        socket.getaddrinfo("huggingface.co", 443)
    except Exception:
        reachable = False
    if not reachable:
        os.environ["HF_ENDPOINT"] = "https://hf-mirror.com"
        print("  [i] huggingface.co 不可达，改用镜像 HF_ENDPOINT=https://hf-mirror.com",
              file=sys.stderr)
    return os.environ.get("HF_ENDPOINT")


def _get_st_model(preferred=None):
    """懒加载 sentence-transformers 模型。

    preferred 不为空时优先尝试该模型（用于与构建时保持一致），
    否则按 ST_MODEL_CANDIDATES 顺序尝试；均失败时返回 None。
    模型使用 HuggingFace 默认缓存目录（~/.cache/huggingface），不在 vault 内存储。
    """
    global _ST_MODEL, _ST_MODEL_NAME
    # 🔴 必须按**索引标记的模型名**复用缓存。旧实现命中 _ST_MODEL 就直接返回，
    #    服务预热过模型 A、索引却由 B 构建时，会用 A 的向量空间去查 B 的索引
    #    （同维时无任何报错，排序静默失真）。
    if preferred and preferred in _ST_MODELS:
        _ST_MODEL = _ST_MODELS[preferred]
        _ST_MODEL_NAME = preferred
        return _ST_MODEL
    if _ST_MODEL is not None and (not preferred or _ST_MODEL_NAME == preferred):
        return _ST_MODEL
    # 必须在导入 sentence_transformers / huggingface_hub 之前配置端点
    _configure_hf_endpoint()
    from sentence_transformers import SentenceTransformer

    candidates = list(ST_MODEL_CANDIDATES)
    if preferred:
        # 把指定模型提到首位（去重）
        candidates = [(preferred, preferred.split("/")[-1])] + \
            [c for c in candidates if c[0] != preferred]

    for model_name, label in candidates:
        try:
            print(f"  加载模型: {label} ...", file=sys.stderr)
            _ST_MODEL = SentenceTransformer(model_name)
            _ST_MODEL_NAME = model_name
            _ST_MODELS[model_name] = _ST_MODEL
            print(f"  模型已加载: {label}", file=sys.stderr)
            return _ST_MODEL
        except Exception as e:
            print(f"  [!] 模型 {label} 加载失败: {e}", file=sys.stderr)
    return None


def _get_tfidf_data():
    """懒加载或构建 TF-IDF + SVD 后端。

    首次调用时从已有嵌入索引加载；若无索引则返回 None（需先 --build）。
    """
    global _TFIDF_DATA
    if _TFIDF_DATA is not None:
        return _TFIDF_DATA
    if not os.path.exists(EMBED_PATH) or not os.path.exists(EMBED_MAP_PATH):
        return None
    # TF-IDF 后端不需要额外加载——嵌入矩阵就是 TF-IDF+SVD 产出
    # 查询时用相同的 vectorizer+svd 转换，但这些需要保存
    # 简化方案：查询时重新 fit（性能差但可用），或保存 vectorizer 状态
    _TFIDF_DATA = {"ready": True}
    return _TFIDF_DATA


# ---------------------------------------------------------------- 编码

def _encode_texts(texts, batch_size=64, show_progress=True,
                  backend=None, st_model_name=None):
    """将文本列表编码为嵌入矩阵 (N, dim)。

    backend 为 None 时自动检测；st_model_name 用于与构建时模型保持一致。
    若 ST 模型加载/下载失败，且 sklearn 可用，则降级到 TF-IDF+SVD。
    """
    if backend is None:
        backend = detect_backend()
    if backend == "st":
        model = _get_st_model(preferred=st_model_name)
        if model is None:
            # 索引明确记录了构建模型 ⇒ 不得用别的后端冒充（静默降级已被报告点名）
            if st_model_name:
                raise RuntimeError(
                    f"嵌入索引由模型 {st_model_name!r} 构建，但该模型当前不可用；"
                    "拒绝改用其他模型/后端，请安装该模型或重建索引")
            if _try_import_sklearn():
                print("  [!] sentence-transformers 模型不可用，降级到 TF-IDF + SVD")
                backend = "tfidf"
            else:
                raise RuntimeError("sentence-transformers 模型加载失败，且无 TF-IDF 降级方案")
        else:
            if st_model_name and _ST_MODEL_NAME != st_model_name:
                raise RuntimeError(
                    f"嵌入索引由模型 {st_model_name!r} 构建，当前实际加载的是 "
                    f"{_ST_MODEL_NAME!r}；同维也不得混用，请安装构建模型或重建索引")
            embeddings = []
            total = len(texts)
            for i in range(0, total, batch_size):
                batch = texts[i:i + batch_size]
                vecs = model.encode(batch, show_progress_bar=False,
                                    normalize_embeddings=True)
                embeddings.append(vecs)
                if show_progress:
                    done = min(i + batch_size, total)
                    print(f"\r  编码进度: {done}/{total}", end="", flush=True)
            if show_progress:
                print()
            return np.vstack(embeddings).astype(np.float32)

    if backend == "tfidf":
        # 构建时用 fit，查询时用 transform
        if show_progress or len(texts) > 10:
            return _encode_tfidf_build(texts, show_progress)
        else:
            # 查询模式：用已保存的 vectorizer/svd
            if os.path.exists(TFIDF_VECTORIZER_PATH):
                return _encode_tfidf_query(texts, show_progress)
            else:
                return _encode_tfidf_build(texts, show_progress)

    raise RuntimeError("无可用嵌入后端，请安装 sentence-transformers 或 scikit-learn")


def _char_tokenize(text):
    """中文按字、英文按词切分（TF-IDF 降级方案用）。"""
    parts = re.findall(r"[A-Za-z]+|\d+|[一-鿿]", text.lower())
    return " ".join(parts)


def _encode_tfidf_build(texts, show_progress=True):
    """TF-IDF + TruncatedSVD 编码（构建模式：fit + transform）。"""
    from sklearn.feature_extraction.text import TfidfVectorizer
    from sklearn.decomposition import TruncatedSVD
    import pickle

    tokenized = [_char_tokenize(t) for t in texts]
    if show_progress:
        print(f"  TF-IDF 向量化 {len(texts)} 篇 ...")
    vectorizer = TfidfVectorizer(max_features=5000, sublinear_tf=True,
                                    token_pattern=r"(?u)\S+")  # 允许单字词
    tfidf_matrix = vectorizer.fit_transform(tokenized)

    dim = min(256, tfidf_matrix.shape[1] - 1, tfidf_matrix.shape[0] - 1)
    if dim < 2:
        dim = min(tfidf_matrix.shape[1], tfidf_matrix.shape[0])
    if show_progress:
        print(f"  SVD 降维至 {dim} 维 ...")
    svd = TruncatedSVD(n_components=dim, random_state=42)
    embeddings = svd.fit_transform(tfidf_matrix)

    # L2 归一化（等价于余弦相似度）
    norms = np.linalg.norm(embeddings, axis=1, keepdims=True)
    norms = np.maximum(norms, 1e-10)
    embeddings = embeddings / norms

    # 保存 vectorizer 和 svd 供查询时复用
    os.makedirs(K.INDEX_DIR, exist_ok=True)
    with open(TFIDF_VECTORIZER_PATH, "wb") as f:
        pickle.dump(vectorizer, f)
    with open(TFIDF_SVD_PATH, "wb") as f:
        pickle.dump(svd, f)

    return embeddings.astype(np.float32)


def _encode_tfidf_query(texts, show_progress=False):
    """TF-IDF 查询编码：用已 fit 的 vectorizer + svd 做 transform。"""
    import pickle

    if not os.path.exists(TFIDF_VECTORIZER_PATH) or not os.path.exists(TFIDF_SVD_PATH):
        raise RuntimeError("TF-IDF 模型文件不存在，请先运行 --build 构建索引")
    with open(TFIDF_VECTORIZER_PATH, "rb") as f:
        vectorizer = pickle.load(f)
    with open(TFIDF_SVD_PATH, "rb") as f:
        svd = pickle.load(f)

    tokenized = [_char_tokenize(t) for t in texts]
    tfidf_matrix = vectorizer.transform(tokenized)
    embeddings = svd.transform(tfidf_matrix)

    # L2 归一化
    norms = np.linalg.norm(embeddings, axis=1, keepdims=True)
    norms = np.maximum(norms, 1e-10)
    embeddings = embeddings / norms

    return embeddings.astype(np.float32)


# ---------------------------------------------------------------- 页面文本准备

def _page_searchable_text(fields):
    """将页面字段拼成适合嵌入的文本。

    按权重重复关键字段，让模型更关注标题/摘要/标签。
    """
    parts = []
    title = fields.get("title", "")
    if title:
        parts.extend([title, title, title])  # 3x 权重
    aliases = fields.get("aliases", "")
    if aliases:
        parts.extend([aliases, aliases])
    summary = fields.get("summary", "")
    if summary:
        parts.append(summary)
    tags = fields.get("tags", "")
    if tags:
        parts.append(tags)
    headings = fields.get("headings", "")
    if headings:
        parts.append(headings)
    body = fields.get("body", "")
    if body:
        # 截断正文避免超长
        parts.append(body[:2000])
    return " ".join(parts)


def _scan_all_pages():
    """扫描全部页面，返回 {name: {fields, text}}。

    🆕 2026-10-22：含 `projects/*/sources/*.md`（项目文献卡）。
    同名时 wiki 页优先——与 `kb_build_index.scan_pages` 保持同一规则。
    """
    pages = {}
    for path in K.iter_page_files(include_projects=True):
        if K.is_excluded(path):
            continue
        raw = K.read_text(path)
        fm_raw, body = K.split_frontmatter(raw)
        fm = K.parse_frontmatter(fm_raw)
        name = os.path.splitext(os.path.basename(path))[0]
        if name in pages and K.is_project_page(path):
            continue
        fields = K.build_fields(name, fm, body)
        text = _page_searchable_text(fields)
        pages[name] = {"fields": fields, "text": text}
    return pages


# ---------------------------------------------------------------- 索引构建

def build_embeddings(show_progress=True):
    """全量构建嵌入索引。"""
    t0 = time.time()
    pages = _scan_all_pages()
    if not pages:
        print("[!] 未找到任何页面")
        return False

    names = sorted(pages.keys())
    texts = [pages[n]["text"] for n in names]

    backend = detect_backend()
    print(f"  共 {len(names)} 个页面待编码")
    embeddings = _encode_texts(texts, show_progress=show_progress, backend=backend)

    # 判定实际使用的后端（ST 模型下载失败时会在 _encode_texts 内降级到 tfidf）
    if backend == "st" and _ST_MODEL is not None:
        actual_backend, actual_model = "st", _ST_MODEL_NAME
    else:
        actual_backend, actual_model = "tfidf", None

    # 保存：矩阵、映射、内容哈希必须来自同一次扫描
    os.makedirs(K.INDEX_DIR, exist_ok=True)
    with open(EMBED_PATH + ".tmp", "wb") as f:
        np.save(f, embeddings)
    os.replace(EMBED_PATH + ".tmp", EMBED_PATH)
    embed_map = {name: i for i, name in enumerate(names)}
    K.write_json_atomic(EMBED_MAP_PATH, embed_map, ensure_ascii=False)
    K.write_json_atomic(EMBED_HASH_PATH,
                        {n: K.content_hash(pages[n]["fields"]) for n in names})
    _write_backend_marker(actual_backend, model=actual_model,
                          dim=int(embeddings.shape[1]), pages=len(names))

    sz = os.path.getsize(EMBED_PATH) / 1024
    elapsed = time.time() - t0
    print(f"[OK] 嵌入索引已构建: {len(names)} 页, "
          f"后端 {actual_backend}, 维度 {embeddings.shape[1]}, 耗时 {elapsed:.1f}s")
    if actual_model:
        print(f"     模型        : {actual_model}")
    print(f"     embeddings.npy : {sz:.0f} KB")
    print(f"     embed_map.json : {os.path.getsize(EMBED_MAP_PATH) / 1024:.1f} KB")
    return True


def add_embeddings(page_rel_paths, show_progress=True):
    """增量更新嵌入索引：仅对指定页面重新编码。"""
    if not os.path.exists(EMBED_PATH) or not os.path.exists(EMBED_MAP_PATH):
        print("[!] 嵌入索引不存在，请先运行全量构建: "
              "python tools/kb_semantic_search.py --build")
        return False

    # 加载现有索引
    embeddings = np.load(EMBED_PATH)
    with open(EMBED_MAP_PATH, "r", encoding="utf-8") as f:
        embed_map = json.load(f)

    # 扫描 wiki 获取最新页面列表
    all_pages = _scan_all_pages()

    # 确定需要更新的页面
    names_to_update = []
    for rel in page_rel_paths:
        name = os.path.splitext(os.path.basename(rel))[0]
        if name in all_pages:
            names_to_update.append(name)
        else:
            print(f"  [!] 页面不存在，跳过: {rel}")

    if not names_to_update:
        print("[!] 无有效页面需要更新")
        return False

    texts = [all_pages[n]["text"] for n in names_to_update]
    print(f"  增量编码 {len(names_to_update)} 个页面 ...")

    # 必须与现有索引的后端保持一致（由标记文件决定）
    backend, model_name = _active_backend()
    if backend == "tfidf" and os.path.exists(TFIDF_VECTORIZER_PATH):
        new_embeds = _encode_tfidf_query(texts)
    else:
        new_embeds = _encode_texts(texts, show_progress=show_progress,
                                   backend=backend, st_model_name=model_name)

    # 维度安全网：防止后端不一致导致矩阵损坏
    if new_embeds.shape[1] != embeddings.shape[1]:
        print(f"[!] 新嵌入维度 ({new_embeds.shape[1]}) 与现有索引 "
              f"({embeddings.shape[1]}) 不一致，请改用全量重建: --build")
        return False

    # 更新矩阵
    for i, name in enumerate(names_to_update):
        if name in embed_map:
            embeddings[embed_map[name]] = new_embeds[i]
        else:
            idx = len(embed_map)
            embed_map[name] = idx
            embeddings = np.vstack([embeddings, new_embeds[i:i+1]])

    # 保存
    with open(EMBED_PATH + ".tmp", "wb") as f:
        np.save(f, embeddings)
    os.replace(EMBED_PATH + ".tmp", EMBED_PATH)
    K.write_json_atomic(EMBED_MAP_PATH, embed_map, ensure_ascii=False)
    K.write_json_atomic(EMBED_HASH_PATH,
                        {n: K.content_hash(all_pages[n]["fields"])
                         for n in embed_map if n in all_pages})

    print(f"[OK] 嵌入索引增量更新: {len(names_to_update)} 页")
    return True


# ---------------------------------------------------------------- 检索

def _load_embeddings():
    """加载嵌入矩阵和映射。"""
    if not os.path.exists(EMBED_PATH) or not os.path.exists(EMBED_MAP_PATH):
        return None, None
    embeddings = np.load(EMBED_PATH)
    with open(EMBED_MAP_PATH, "r", encoding="utf-8") as f:
        embed_map = json.load(f)
    return embeddings, embed_map


def _load_meta():
    """加载 meta.json 用于获取 summary 等元数据。"""
    if not os.path.exists(K.META_PATH):
        return None
    with open(K.META_PATH, "r", encoding="utf-8") as f:
        return json.load(f)


def _current_page_names():
    """当前参与检索的页面名 = wiki 页 + 项目卡（不含 .index 等）。

    🆕 2026-10-22：项目卡已进嵌入索引；若此处只数 wiki 页，50 张卡会被判成
    「幽灵条目」，freshness 永远 FAIL —— 校验器口径必须与索引口径一致。
    """
    names = set()
    for d in K.PAGE_DIRS:
        full = os.path.join(K.WIKI, d)
        if not os.path.isdir(full):
            continue
        for f in os.listdir(full):
            if f.endswith(".md"):
                names.add(f[:-3])
    names.update(K.project_page_paths().keys())
    return names


def diff_embed_coverage(indexed, current):
    """纯函数：比较「已嵌入集合」与「当前页面集合」。返回 (missing, stale, ok)。

    单列出来是为了能被 `--selftest` 直接反算——本判据决定了
    「语义检索是否敢出结果」，一旦判错就是**静默漏召回**，
    正是 CLAUDE.md 记的头号失真形态（页面在语义层永远召回不到且不报错）。
    """
    indexed = set(indexed)
    current = set(current)
    missing = sorted(current - indexed)   # 库里有、索引里没有 → 永远召回不到
    stale = sorted(indexed - current)     # 索引里有、库里已无 → 幽灵条目
    return missing, stale, not missing and not stale


def diff_embed_hashes(indexed, current):
    """找出未记录哈希或同名内容已变化的页面。"""
    changed = [n for n, h in current.items() if indexed.get(n) != h]
    return sorted(changed), not changed


def pages_newer_than(meta_path, page_paths):
    """返回 mtime 晚于 meta_path 的页面名。

    🔴 为什么需要这一层（2026-10-24 补）
    ------------------------------------
    旧实现把 `embed_hashes.json` 与 **`meta_full.json` 里记录的哈希**比较。
    但 `meta_full.json` 本身是派生数据：改了页面却**没跑 `kb_build_index.py`** 时，
    两边都还是旧值，freshness 判「新鲜」，语义检索继续返回旧向量且不报警。
    这里用文件 mtime 做一道**廉价的前置门禁**：只要有页面比 meta_full 新，
    就说明 meta（进而嵌入）已陈旧。内容级哈希比较仍保留在下一层。
    纯函数（路径入参）以便 selftest 用临时文件反算。
    """
    try:
        meta_mtime = os.path.getmtime(meta_path)
    except OSError:
        return None
    newer = []
    for p in page_paths:
        try:
            if os.path.getmtime(p) > meta_mtime:
                newer.append(os.path.splitext(os.path.basename(p))[0])
        except OSError:
            continue
    return sorted(set(newer))


def check_index_freshness(embed_map, verbose=True):
    """校验嵌入索引覆盖的页面集合、同名内容哈希是否与当前库一致。

    🔴 为什么必须有这个函数
    ----------------------
    早期版本 `semantic_search()` **只校验向量维度**（见下方 shape 判断），
    因此当嵌入索引停在 471 页、而知识库已增长到 583 页时，
    **112 个页面（其中 95 个 source）在语义检索与混合检索下永远不可能被召回，
    且不报任何错误**。用户与 Agent 都无从察觉。

    这正是 CLAUDE.md 反复警告的形态：「**宽松的校验器等于没有校验器**」，
    以及「计数器本身出错，却被读成内容质量问题」。

    返回 (missing, stale, ok)。ok=False 时调用方**应当拒绝出结果**，而不是降级静默。
    """
    current = _current_page_names()
    indexed = set(embed_map.keys())
    missing, stale, ok = diff_embed_coverage(indexed, current)
    changed = []
    newer = []
    if ok:
        try:
            with open(EMBED_HASH_PATH, encoding="utf-8") as f:
                indexed_hashes = json.load(f)
            with open(K.FULL_PATH, encoding="utf-8") as f:
                full_pages = json.load(f).get("pages", {})
            current_hashes = {n: full_pages[n]["hash"] for n in current
                              if n in full_pages and full_pages[n].get("hash")}
            changed, hash_ok = diff_embed_hashes(indexed_hashes, current_hashes)
            changed = sorted(set(changed) | (current - set(current_hashes)))
            # 页面文件比 meta_full 新 ⇒ meta（以及嵌入）已陈旧；见 pages_newer_than
            newer = pages_newer_than(
                K.FULL_PATH, list(K.iter_page_files(include_projects=True))) or []
            changed = sorted(set(changed) | set(newer))
            ok = hash_ok and len(current_hashes) == len(current)
            ok = ok and not newer
        except (OSError, ValueError, KeyError, json.JSONDecodeError):
            changed = sorted(current)
            ok = False
    if verbose and not ok:
        print(f"[!] 嵌入索引与当前页面集合或内容**不一致**：", file=sys.stderr)
        print(f"      当前页面 {len(current)}  |  已嵌入 {len(indexed)}", file=sys.stderr)
        print(f"      缺失 {len(missing)} 页｜同名内容变化/无哈希 {len(changed)} 页",
              file=sys.stderr)
        if newer:
            print(f"      其中 {len(newer)} 页的文件 mtime 晚于 meta_full.json"
                  f"（改页后未重建索引）", file=sys.stderr)
        for m in (missing + changed)[:8]:
            print(f"        - {m}", file=sys.stderr)
        if stale:
            print(f"      幽灵条目 {len(stale)} 页（索引里有、库里已无）", file=sys.stderr)
        print("      ⇒ 修复：python tools/kb.py index build && "
              "python tools/kb.py index embed", file=sys.stderr)
    return sorted(set(missing + changed)), stale, ok


def _meta_of(meta, name):
    """从 meta 中取 (summary, updated, tags, aliases, type)。"""
    if meta is None:
        return "", "", [], [], ""
    if name in meta.get("pages", {}):
        t, s, u, tags, al, _ = meta["pages"][name]
        return s, u, tags, al, t
    for row in meta.get("sources", []):
        if row[0] == name:
            return row[2], row[1], row[3], row[4], "source"
    return "", "", [], [], ""


def semantic_search(query, top_k=10):
    """语义检索：返回 [(name, score)]。"""
    embeddings, embed_map = _load_embeddings()
    if embeddings is None:
        print("[!] 嵌入索引不存在，请先运行: "
              "python tools/kb_semantic_search.py --build",
              file=sys.stderr)
        return []

    # 编码查询（后端须与索引一致，由标记文件决定）
    backend, model_name = _active_backend()
    if backend == "tfidf" and os.path.exists(TFIDF_VECTORIZER_PATH):
        q_vec = _encode_tfidf_query([query])
    else:
        q_vec = _encode_texts([query], show_progress=False,
                              backend=backend, st_model_name=model_name)
    q_vec = q_vec[0]

    # 维度安全网
    if q_vec.shape[0] != embeddings.shape[1]:
        print(f"[!] 查询向量维度 ({q_vec.shape[0]}) 与索引 ({embeddings.shape[1]}) "
              f"不一致，请重新构建索引: --build", file=sys.stderr)
        return []

    # 🔴 页面集合安全网（2026-10-04 新增）：维度对了不代表索引没过期。
    #    不加这一步，索引缺 112 页时仍会「正常」返回结果，静默漏检。
    _, _, fresh = check_index_freshness(embed_map)
    if not fresh:
        print("[!] 拒绝返回可能漏检的结果。请先重建索引："
              "python tools/kb_semantic_search.py --build", file=sys.stderr)
        return []

    # 余弦相似度（向量已 L2 归一化，点积即余弦）
    scores = embeddings @ q_vec  # (N,)

    # 反向映射：行号 → 页面名
    idx_to_name = {i: n for n, i in embed_map.items()}

    # 取 top-K
    top_indices = np.argsort(-scores)[:top_k]
    results = []
    for idx in top_indices:
        name = idx_to_name.get(int(idx))
        if name and scores[idx] > 0:
            results.append((name, float(scores[idx])))
    return results


def _bm25_search(query, top_k=50):
    """调用 BM25 检索（用于混合模式）。

    复用 kb_search.py 的核心逻辑，返回 [(name, score)]。
    """
    try:
        import kb_search as KS
    except ImportError:
        return []

    if not os.path.exists(K.META_PATH) or not os.path.exists(K.BM25_PATH):
        return []

    with open(K.META_PATH, "r", encoding="utf-8") as f:
        meta = json.load(f)
    with open(K.BM25_PATH, "r", encoding="utf-8") as f:
        bm = json.load(f)

    alias_hits = KS.resolve_aliases(query, meta.get("alias_map", {}))
    strong = [(a, c) for a, c in alias_hits if len(a) >= 3]
    if not strong:
        strong = alias_hits[:1]

    qtokens = K.tokenize(query)
    canon_names = [c for _, c in strong]
    for c in canon_names:
        qtokens.extend(K.tokenize(c))
    for a, c in alias_hits:
        if c not in canon_names:
            qtokens.extend(K.tokenize(c))

    ranked = KS.bm25_score(qtokens, bm, canon_names, query_raw=query)
    return ranked[:top_k]


def hybrid_search(query, top_k=10, rrf_k=60):
    """混合检索：BM25 + 语义 RRF 融合。

    RRF 公式: score(d) = sum(1/(k+rank_bm25(d)) + 1/(k+rank_semantic(d)))
    """
    bm25_results = _bm25_search(query, top_k=top_k * 3)
    sem_results = semantic_search(query, top_k=top_k * 3)

    if not bm25_results and not sem_results:
        return []
    if not bm25_results:
        return sem_results[:top_k]
    if not sem_results:
        return bm25_results[:top_k]

    # RRF 融合
    rrf_scores = {}
    for rank, (name, _score) in enumerate(bm25_results, 1):
        rrf_scores[name] = rrf_scores.get(name, 0.0) + 1.0 / (rrf_k + rank)
    for rank, (name, _score) in enumerate(sem_results, 1):
        rrf_scores[name] = rrf_scores.get(name, 0.0) + 1.0 / (rrf_k + rank)

    ranked = sorted(rrf_scores.items(), key=lambda kv: -kv[1])
    return ranked[:top_k]


# ---------------------------------------------------------------- CLI

def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    ⚠️ 刻意**不加载模型**（那要 ~20 s 冷启动），只钉住集合判据与纯函数——
    因为这些才是「敢不敢出结果」的守门逻辑。
    """
    import os as _os
    import json as _json
    ok = True

    # 正例：两侧完全一致 → ok
    m, s, good = diff_embed_coverage({"A", "B"}, {"A", "B"})
    print(f"  [{'ok' if good else 'FAIL'}] 正例 集合一致 -> ok={good}")
    ok = ok and good

    # 🔴 关键正例：库里有、索引没有 → **必须** ok=False
    #    （这就是当年 112 页在语义检索下永远召回不到的形态）
    m, s, good = diff_embed_coverage({"A"}, {"A", "B", "C"})
    cond = (not good) and m == ["B", "C"] and s == []
    print(f"  [{'ok' if cond else 'FAIL'}] 🔴 缺失页必须判「不新鲜」 -> "
          f"missing={m} ok={good}")
    ok = ok and cond

    # 正例：索引里有、库里已无 → 幽灵条目，同样 ok=False
    m, s, good = diff_embed_coverage({"A", "ghost"}, {"A"})
    cond = (not good) and m == [] and s == ["ghost"]
    print(f"  [{'ok' if cond else 'FAIL'}] 幽灵条目判「不新鲜」 -> stale={s} ok={good}")
    ok = ok and cond

    # 反例：两侧都空 → 一致（不得因「空」而误报不一致）
    m, s, good = diff_embed_coverage(set(), set())
    print(f"  [{'ok' if good else 'FAIL'}] 反例 双空集合一致 -> ok={good}")
    ok = ok and good

    # 正例：接受任意可迭代（调用方可能传 list / dict_keys）
    m, s, good = diff_embed_coverage(["A", "B"], ["B", "A"])
    print(f"  [{'ok' if good else 'FAIL'}] 正例 可迭代类型无关 -> ok={good}")
    ok = ok and good

    changed, good = diff_embed_hashes({"A": "1"}, {"A": "1"})
    cond = good and not changed
    print(f"  [{'ok' if cond else 'FAIL'}] 同名同内容哈希判新鲜")
    ok = ok and cond
    changed, good = diff_embed_hashes({"A": "1"}, {"A": "2"})
    cond = not good and changed == ["A"]
    print(f"  [{'ok' if cond else 'FAIL'}] 同名内容修改必须判不新鲜")
    ok = ok and cond

    # 页面文件晚于 meta_full ⇒ 必须判 **陈旧**（否则「改页未重建」静默返回旧向量）
    import tempfile
    import time as _time
    with K.temp_dir(prefix="kb_semantic_") as _td:
        _mp = _os.path.join(_td, "meta_full.json")
        _old = _os.path.join(_td, "old.md")
        _new = _os.path.join(_td, "new.md")
        for _p in (_mp, _old, _new):
            with open(_p, "w", encoding="utf-8") as _f:
                _f.write("x")
        _now = _time.time()
        _os.utime(_mp, (_now, _now))
        _os.utime(_old, (_now - 10, _now - 10))
        _os.utime(_new, (_now + 10, _now + 10))
        _got = pages_newer_than(_mp, [_old, _new])
        cond = _got == ["new"]
        print(f"  [{'ok' if cond else 'FAIL'}] 🔴 页面晚于 meta_full 必须判陈旧 -> {_got}")
        ok = ok and cond
        cond = pages_newer_than(_os.path.join(_td, "missing.json"), [_old]) is None
        print(f"  [{'ok' if cond else 'FAIL'}] 反例 meta 缺失返回 None（不猜）")
        ok = ok and cond

    # 正例：真实索引可读且覆盖自洽（用真实数据反算一次）
    p = "wiki/.index/embed_map.json"
    if _os.path.exists(p):
        em = _json.load(open(p, encoding="utf-8"))
        cur = _current_page_names()
        m, s, good = diff_embed_coverage(em.keys(), cur)
        print(f"  [{'ok' if good else 'WARN'}] 真实索引覆盖 -> "
              f"嵌入 {len(em)} / 当前 {len(cur)} / 缺失 {len(m)} / 幽灵 {len(s)}")
        ok = ok and good
    else:
        print("  [info] 未找到 embed_map.json，跳过真实覆盖检查")

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(
        description="语义检索 / 混合检索")
    ap.add_argument("--build", action="store_true",
                    help="构建嵌入索引")
    ap.add_argument("--add", nargs="+", metavar="PAGE",
                    help="增量更新指定页面（相对于 wiki/ 的路径）")
    ap.add_argument("--query", type=str, default="",
                    help="语义检索查询")
    ap.add_argument("--hybrid", type=str, default="",
                    help="混合检索（BM25 + 语义 RRF 融合）")
    ap.add_argument("-k", type=int, default=10, help="返回条数")
    ap.add_argument("--json", action="store_true", help="JSON 输出")
    ap.add_argument("--selftest", action="store_true",
                    help="校验器自检（**不加载模型**，只钉集合判据与纯函数）")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    # 构建模式
    if args.build:
        backend = detect_backend()
        if backend is None:
            print("[!] 无可用嵌入后端。请安装以下之一：")
            print("    pip install sentence-transformers")
            print("    pip install scikit-learn")
            return 1
        print(f"后端: {'sentence-transformers' if backend == 'st' else 'TF-IDF + SVD (降级)'}")
        ok = build_embeddings()
        return 0 if ok else 1

    # 增量更新
    if args.add:
        ok = add_embeddings(args.add)
        return 0 if ok else 1

    # 语义检索
    if args.query:
        results = semantic_search(args.query, top_k=args.k)
        # 空结果有两种：真的没有正分命中 vs 索引缺失/过期。后者必须非零退出，
        # 否则自动化会把「索引没建」当成「库里没有」。
        if not results:
            _emb, _emap = _load_embeddings()
            if _emb is None or _emap is None:
                return 3
            _m, _s, _fresh = check_index_freshness(_emap, verbose=False)
            if not _fresh:
                return 3
        meta = _load_meta()
        _print_results(args.query, results, meta, args.json, mode="语义")
        return 0

    # 混合检索：兼容入口同样强制精排，不把 RRF 当作 reranker
    if args.hybrid:
        import kb_rag
        try:
            data = kb_rag.retrieve(args.hybrid, k=args.k, mode="hybrid")
        except kb_rag.RetrievalUnavailable as exc:
            print(f"[!] {exc}", file=sys.stderr)
            return 3
        if args.json:
            print(K.json_dumps(data, ensure_ascii=False, indent=1))
        else:
            print(f'[混合+精排] 查询: "{args.hybrid}"   命中 {data["count"]} 条\n')
            for item in data["results"]:
                print(f"{item['rank']:>2}. [{item['type']}] {item['name']}   "
                      f"{item['score']:.4f}")
        return 0

    ap.print_help()
    return 1


def _print_results(query, results, meta, as_json=False, mode="语义"):
    """统一输出格式。"""
    if as_json:
        out = []
        for name, score in results:
            s, u, tags, al, t = _meta_of(meta, name)
            out.append({"name": name, "type": t, "score": round(score, 4),
                        "summary": s, "updated": u})
        print(json.dumps({"mode": mode, "query": query, "results": out},
                         ensure_ascii=False, indent=1))
        return

    print(f'[{mode}] 查询: "{query}"   命中 {len(results)} 条\n')
    for i, (name, score) in enumerate(results, 1):
        s, u, tags, al, t = _meta_of(meta, name)
        print(f"{i:>2}. [{t}] {name}   ({score:.4f}, 更新 {u})")
        if s:
            print(f"    {s[:150]}{'...' if len(s) > 150 else ''}")


if __name__ == "__main__":
    sys.exit(main())
